/* MSG-01 · Lista de Hilos — estilos de la pantalla.
   El contenedor de scroll/fondo lo aporta el shell; aquí solo el contenido. */

.page {
  min-width: 0;
}

.eyebrow {
  margin: 0 0 4px;
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
}

.title {
  margin: 0 0 3px;
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
}

.subtitle {
  margin: 0 0 16px;
  max-width: 560px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

.e2eeStatus {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  width: fit-content;
  margin-bottom: 14px;
  padding: 6px 10px;
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  border-radius: 5px;
  font-family: var(--bw-font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--bw-signal-green);
}

.actionsBar {
  display: flex;
  align-items: flex-start;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 14px;
}

.searchForm {
  position: relative;
  flex: 0 1 300px;
}

.searchIcon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--bw-input-placeholder);
  font-size: 15px;
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  outline: none;
  font-family: var(--bw-font-body);
  font-size: 13px;
  color: var(--bw-input-text);
  transition: border-color 0.15s, box-shadow 0.15s;
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.newContact {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 3px;
}

.btnPrimary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  color: var(--bw-warm-cream);
  border: none;
  border-radius: 5px;
  font-family: var(--bw-font-body);
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  cursor: not-allowed;
  opacity: 0.6;
}

.newContactReason {
  font-size: 11px;
  line-height: 1.4;
  color: var(--bw-steel-mist);
  max-width: 210px;
}

.threadCount {
  align-self: center;
  margin-left: auto;
  font-size: 12px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.status {
  margin: 0;
  padding: 40px 18px;
  text-align: center;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  font-size: 14px;
  color: var(--bw-steel-mist);
}

/* F-127: solo el fallo que interrumpe la pantalla lleva role="alert"; el aviso
   enseña además el error real del servidor (F-128). */
.error {
  padding: 16px 18px;
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 5px;
  font-size: 13px;
  line-height: 1.5;
  color: var(--bw-error-text);
}

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageBtn,
.pageCtrl {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 30px;
  min-width: 30px;
  padding: 0 8px;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  font-family: var(--bw-font-body);
  font-size: 12px;
  color: var(--bw-ink-steel);
  cursor: pointer;
  line-height: 1;
}

.pageBtn:hover,
.pageCtrl:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageBtnCurrent,
.pageBtnCurrent:hover {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
  cursor: default;
}

.pageCtrl:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.pageCtrl:disabled:hover {
  border-color: var(--bw-line-steel-strong);
  color: var(--bw-ink-steel);
}

