import { useEffect, useState, type FormEvent } from 'react';
import type { MemberProfile } from '../../lib/session';
import { fetchThreadPage, pageCount, type ThreadPage } from '../../lib/threads';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

/**
 * MSG-01 · Lista de Hilos (pantalla).
 *
 * Es la pantalla, no un componente de presentación: posee el estado de búsqueda
 * y de página, llama a `fetchThreadPage` con `profile.orgId` y pinta los
 * estados de carga, error y datos.
 */
interface MessagesProps {
  profile: MemberProfile;
  /**
   * Inyectable para que los tests no dependan del reloj. Tipo ampliado a
   * `Date | undefined` por F-137: `exactOptionalPropertyTypes` rechazaría pasar
   * `undefined` a una prop declarada solo como `Date`.
   */
  now?: Date | undefined;
  /**
   * F-118: el shell cableó esta prop desde App.tsx después de escribirse esta
   * tarea; es la firma pública del componente. MSG-02 no existía entonces y
   * abrir un hilo no lleva a ningún sitio, así que la prop se recibe y se
   * ignora.
   */
  onOpenThread?: (threadId: string) => void;
}

/** Formateo con Intl en es-ES; nunca a mano (F-024). */
const COUNT_FMT = new Intl.NumberFormat('es-ES', { useGrouping: false });

/** MSG-02 no existe en el MVP: la apertura de un hilo no lleva a ninguna parte. */
const NO_OPEN = () => undefined;

/**
 * F-128: PostgREST rechaza con un objeto plano { code, message }, de modo que
 * `String(e)` daría `[object Object]` y `e.message` daría `undefined`. Este
 * helper saca `code` y/o `message` cuando existen.
 */
function describeError(err: unknown): string {
  if (err && typeof err === 'object') {
    const { code, message } = err as { code?: unknown; message?: unknown };
    const codePart = typeof code === 'string' && code.length > 0 ? code : '';
    const messagePart = typeof message === 'string' && message.length > 0 ? message : '';
    if (codePart || messagePart) {
      return `${codePart} ${messagePart}`.trim();
    }
    if (err instanceof Error && err.message.length > 0) {
      return err.message;
    }
    try {
      return JSON.stringify(err);
    } catch {
      return String(err);
    }
  }
  if (err instanceof Error && err.message.length > 0) {
    return err.message;
  }
  return String(err);
}

export function Messages({ profile, now = new Date() }: MessagesProps) {
  const [searchInput, setSearchInput] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [data, setData] = useState<ThreadPage | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchThreadPage({ orgId: profile.orgId, search, page })
      .then((result) => {
        if (!cancelled) {
          setData(result);
          setLoading(false);
        }
      })
      .catch((err: unknown) => {
        if (!cancelled) {
          setError(`No se pudieron cargar los hilos. ${describeError(err)}`);
          setLoading(false);
        }
      });

    return () => {
      cancelled = true;
    };
  }, [profile.orgId, search, page]);

  function handleSearchSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSearch(searchInput.trim());
    setPage(1);
  }

  const pages = data ? pageCount(data.total) : 1;

  function goToPage(next: number) {
    if (next >= 1 && next <= pages) {
      setPage(next);
    }
  }

  return (
    <div className={styles.page}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a
        extremo.
      </p>

      <div className={styles.e2eeStatus}>
        <i className="ti ti-lock" aria-hidden="true" />
        <span>E2EE activo · contenido cifrado de extremo a extremo</span>
      </div>

      <div className={styles.actionsBar}>
        <form className={styles.searchForm} role="search" onSubmit={handleSearchSubmit}>
          <i className={`ti ti-search ${styles.searchIcon}`} aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            aria-label="Buscar por nombre de organización"
            value={searchInput}
            onChange={(event) => setSearchInput(event.target.value)}
          />
        </form>

        <div className={styles.newContact}>
          {/* DIR-01 queda fuera del alcance del MVP (Plan §9): el control se pinta
              deshabilitado y con el motivo visible, como el botón de subida de INV-01. */}
          <button type="button" className={styles.btnPrimary} disabled>
            <i className="ti ti-address-book" aria-hidden="true" />
            Nuevo contacto
          </button>
          <span className={styles.newContactReason} data-testid="directorio-scope">
            El Directorio queda fuera del MVP en esta versión
          </span>
        </div>

        {!loading && data && (
          <span className={styles.threadCount} data-testid="pag-info">
            {COUNT_FMT.format(data.total)} hilos · Página {COUNT_FMT.format(page)} de{' '}
            {COUNT_FMT.format(pages)}
          </span>
        )}
      </div>

      {loading && (
        <p className={styles.status} role="status">
          Cargando hilos…
        </p>
      )}

      {!loading && error && (
        <div role="alert" className={styles.error}>
          {error}
        </div>
      )}

      {!loading && !error && data && (
        <>
          <ThreadList threads={data.threads} now={now} onOpen={NO_OPEN} />

          <nav className={styles.pagination} aria-label="Paginación de hilos">
            <button
              type="button"
              className={styles.pageCtrl}
              disabled={page <= 1}
              aria-label="Página anterior"
              onClick={() => goToPage(page - 1)}
            >
              ‹
            </button>

            {Array.from({ length: pages }, (_, i) => i + 1).map((p) => (
              <button
                key={p}
                type="button"
                className={p === page ? `${styles.pageBtn} ${styles.pageBtnCurrent}` : styles.pageBtn}
                aria-current={p === page ? 'page' : undefined}
                onClick={() => goToPage(p)}
              >
                {p}
              </button>
            ))}

            <button
              type="button"
              className={styles.pageCtrl}
              disabled={page >= pages}
              aria-label="Página siguiente"
              onClick={() => goToPage(page + 1)}
            >
              ›
            </button>
          </nav>
        </>
      )}
    </div>
  );
}

