/* MSG-01 · Lista de hilos — estilos de presentación.
   La tarjeta del mock es blanca pura y no existe un token blanco en el sistema;
   --bw-warm-cream es el neutro claro más cercano disponible. */

.list {
  margin: 0;
  padding: 0;
  list-style: none;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

.row {
  border-bottom: 1px solid var(--bw-surface-mist);
}

.row:last-child {
  border-bottom: none;
}

.rowButton {
  display: block;
  width: 100%;
  padding: 14px 18px;
  background: transparent;
  border: none;
  border-radius: 0;
  cursor: pointer;
  text-align: left;
  font-family: var(--bw-font-body);
  font-size: 14px;
}

.rowButton:hover {
  background: var(--bw-row-hover-tint);
}

.rowTop {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.orgGroup {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.orgName {
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.countryBadge {
  display: inline-block;
  font-family: var(--bw-font-mono);
  font-size: 10px;
  line-height: 1.4;
  padding: 1px 6px;
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-line-steel);
  white-space: nowrap;
}

.rowTime {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  color: var(--bw-steel-mist);
  white-space: nowrap;
}

.rowBottom {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 6px;
  min-width: 0;
}

.preview {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  color: var(--bw-steel-mist);
}

.stateBadge {
  flex-shrink: 0;
  display: inline-block;
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 7px;
  border-radius: 2px;
  border: 1px solid transparent;
  white-space: nowrap;
}

.badgeNeutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border-color: var(--bw-badge-neutral-border);
}

.badgeInfo {
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border-color: var(--bw-chip-active-border);
}

.badgeWarn {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border-color: var(--bw-badge-warning-border);
}

.badgeSuccess {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border-color: var(--bw-badge-success-border);
}

.badgeClosed {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-input-placeholder);
  border-color: var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

/* Estado vacío: fuera de cualquier <ul>, para que no queden `listitem` (F-141). */
.emptyState {
  padding: 36px 24px;
  text-align: center;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
}

.emptyMessage {
  margin: 0 0 16px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-deep-steel);
}

.emptyCta {
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  color: var(--bw-warm-cream);
  border: none;
  border-radius: 5px;
  font-family: var(--bw-font-body);
  font-size: 13px;
  font-weight: 500;
  cursor: not-allowed;
  opacity: 0.6;
}

.emptyHint {
  margin: 8px 0 0;
  font-size: 12px;
  color: var(--bw-steel-mist);
}

