import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * MSG-01 · Lista de hilos (presentacional).
 *
 * Recibe las filas ya ordenadas por el servidor y las pinta en ese mismo orden.
 * No carga datos ni pagina: eso vive en `Messages`.
 *
 * El patrón de fila pulsable es un `<button>` DENTRO del `<li>` (F-131): el `<li>`
 * conserva su rol nativo `listitem` y el botón es quien recibe el nombre
 * accesible del hilo. Nunca se pone un `role="button"` encima del `<li>`, porque
 * eso sustituiría su rol `listitem` y, si además hay un botón dentro, duplicaría
 * el nombre accesible.
 */

/** Clase de tono por estado. F-143: la propiedad puede faltar en el CSS module,
 *  así que el diccionario admite `undefined` y el consumo resuelve con `?? ''`. */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.badgeNeutral,
  info: styles.badgeInfo,
  warn: styles.badgeWarn,
  success: styles.badgeSuccess,
  closed: styles.badgeClosed,
};

interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj (F-137). */
  now?: Date | undefined;
  /** Avisa con el ID del hilo al abrirlo; nunca con el objeto. */
  onOpen: (id: string) => void;
}

export function ThreadList({ threads, now, onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    // F-141: el estado vacío NO se envuelve en un <li> dentro del <ul>. Con
    // threads vacío no debe quedar ningún `listitem` en el documento.
    return (
      <div className={styles.emptyState}>
        <p className={styles.emptyMessage}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras
          organizaciones.
        </p>
        <button type="button" className={styles.emptyCta} disabled>
          Ir al Directorio
        </button>
        <p className={styles.emptyHint}>El Directorio queda fuera del MVP en esta versión.</p>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((thread) => {
        const toneClass = TONE_CLASS[stateTone(thread.state)] ?? '';
        return (
          <li key={thread.id} className={styles.row}>
            <button
              type="button"
              className={styles.rowButton}
              onClick={() => onOpen(thread.id)}
            >
              <span className={styles.rowTop}>
                <span className={styles.orgGroup}>
                  <span className={styles.orgName}>{thread.counterpartyName}</span>
                  {thread.counterpartyCountry.length > 0 && (
                    <span className={styles.countryBadge}>{thread.counterpartyCountry}</span>
                  )}
                </span>
                <span className={styles.rowTime}>{relativeTime(thread.lastItemAt, now)}</span>
              </span>

              {/* Vista previa de METADATOS únicamente; nunca contenido descifrado. */}
              <span className={styles.rowBottom}>
                <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
                <span className={`${styles.stateBadge} ${toneClass}`}>{thread.state}</span>
              </span>
            </button>
          </li>
        );
      })}
    </ul>
  );
}
